import { existsSync, readFileSync } from 'node:fs';
import { inflateSync } from 'node:zlib';
import { describe, expect, it } from 'vitest';
import { faviconSvg, ICONS, PRO_ICONS } from '../scripts/generate-mascot-icons';
import { appleTouchIconFile } from '#lib/shared/pro-look';

// FN-44 Part 5: the favicon and home-screen icons are Koko, generated by scripts/generate-mascot-icons.ts.

interface Png {
	width: number;
	height: number;
	/** 2 = RGB, 6 = RGBA. */
	colorType: number;
	/** RGBA per pixel. */
	pixels: Uint8Array;
}

/** A small PNG reader for 8-bit RGB/RGBA, non-interlaced files (what Chromium's screenshots are). */
function readPng(file: string): Png {
	const buf = readFileSync(file);
	expect(buf.subarray(0, 8)).toEqual(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]));
	let offset = 8;
	let header: {
		width: number;
		height: number;
		depth: number;
		colorType: number;
		interlace: number;
	} | null = null;
	const idat: Buffer[] = [];
	while (offset < buf.length) {
		const length = buf.readUInt32BE(offset);
		const type = buf.toString('latin1', offset + 4, offset + 8);
		const data = buf.subarray(offset + 8, offset + 8 + length);
		if (type === 'IHDR')
			header = {
				width: data.readUInt32BE(0),
				height: data.readUInt32BE(4),
				depth: data[8]!,
				colorType: data[9]!,
				interlace: data[12]!
			};
		else if (type === 'IDAT') idat.push(data);
		offset += 12 + length;
	}
	if (!header) throw new Error(`${file}: no IHDR`);
	const { width, height, depth, colorType, interlace } = header;
	expect([depth, interlace]).toEqual([8, 0]);
	expect([2, 6]).toContain(colorType);
	const bpp = colorType === 6 ? 4 : 3;
	const raw = inflateSync(Buffer.concat(idat));
	const stride = width * bpp;
	const out = new Uint8Array(height * stride);
	for (let y = 0; y < height; y++) {
		const filter = raw[y * (stride + 1)]!;
		const line = raw.subarray(y * (stride + 1) + 1, (y + 1) * (stride + 1));
		for (let i = 0; i < stride; i++) {
			const a = i >= bpp ? out[y * stride + i - bpp]! : 0;
			const b = y > 0 ? out[(y - 1) * stride + i]! : 0;
			const c = y > 0 && i >= bpp ? out[(y - 1) * stride + i - bpp]! : 0;
			const p = a + b - c;
			const [pa, pb, pc] = [Math.abs(p - a), Math.abs(p - b), Math.abs(p - c)];
			const predictor = [0, a, b, (a + b) >> 1, pa <= pb && pa <= pc ? a : pb <= pc ? b : c][
				filter
			]!;
			out[y * stride + i] = (line[i]! + predictor) & 0xff;
		}
	}
	const pixels = new Uint8Array(width * height * 4);
	for (let i = 0; i < width * height; i++) {
		pixels.set(out.subarray(i * bpp, i * bpp + 3), i * 4);
		pixels[i * 4 + 3] = bpp === 4 ? out[i * bpp + 3]! : 255;
	}
	return { width, height, colorType, pixels };
}

/** True where a pixel is part of Koko (not the white background and not transparent). */
const isArt = (png: Png, x: number, y: number) => {
	const i = (y * png.width + x) * 4;
	const [r, g, b, a] = png.pixels.subarray(i, i + 4);
	return a! > 0 && !(r === 255 && g === 255 && b === 255);
};

const manifest = JSON.parse(readFileSync('src/lib/server/pwa/manifest.webmanifest', 'utf8')) as {
	icons: { src: string; sizes: string; purpose: string }[];
};

describe('manifest icons', () => {
	it('five entries (192 and 512 any, 192 and 512 maskable, 512 monochrome), each an existing PNG of the declared size', () => {
		expect(manifest.icons.map((i) => `${i.sizes} ${i.purpose}`)).toEqual([
			'192x192 any',
			'512x512 any',
			'192x192 maskable',
			'512x512 maskable',
			'512x512 monochrome'
		]);
		for (const icon of manifest.icons) {
			const png = readPng(`static${icon.src}`);
			expect(`${png.width}x${png.height}`, icon.src).toBe(icon.sizes);
		}
	});

	it.each(ICONS.map((s) => [s.file, s] as const))(
		'%s shows Koko: black fur, ink outline',
		(file) => {
			const png = readPng(`static/${file}`);
			let accent = 0;
			let ink = 0;
			for (let i = 0; i < png.pixels.length; i += 4) {
				const [r, g, b] = png.pixels.subarray(i, i + 3);
				if (r === 0x3a && g === 0x33 && b === 0x2f) accent++;
				if (r === 0x17 && g === 0x17 && b === 0x17) ink++;
			}
			// Koko's fur covers a good part of the icon; its outline is drawn too.
			expect(accent / (png.width * png.height)).toBeGreaterThan(0.1);
			expect(ink).toBeGreaterThan(0);
		}
	);

	it.each(['192', '512'])(
		'maskable %s: every drawn pixel lies inside the centre safe-zone circle (80 % of the icon)',
		(size) => {
			const png = readPng(`static/icons/icon-maskable-${size}.png`);
			const r = 0.4 * png.width;
			const centre = png.width / 2;
			let drawn = 0;
			for (let y = 0; y < png.height; y++)
				for (let x = 0; x < png.width; x++) {
					if (!isArt(png, x, y)) continue;
					drawn++;
					expect(Math.hypot(x + 0.5 - centre, y + 0.5 - centre), `${x},${y}`).toBeLessThanOrEqual(
						r
					);
				}
			expect(drawn).toBeGreaterThan(Number(size) === 512 ? 10_000 : 1_500);
		}
	);

	it('monochrome 512 (FN-13b): alpha only, transparent around Koko, one colour, inside the safe zone', () => {
		const png = readPng('static/icons/icon-monochrome-512.png');
		expect(png.colorType).toBe(6);
		let opaque = 0;
		let transparent = 0;
		const r = 0.4 * png.width;
		for (let y = 0; y < png.height; y++)
			for (let x = 0; x < png.width; x++) {
				const i = (y * png.width + x) * 4;
				const a = png.pixels[i + 3]!;
				if (a === 0) transparent++;
				else {
					opaque++;
					expect([...png.pixels.subarray(i, i + 3)], `${x},${y}`).toEqual([0, 0, 0]);
					expect(Math.hypot(x + 0.5 - 256, y + 0.5 - 256)).toBeLessThanOrEqual(r);
				}
			}
		expect(transparent / (png.width * png.height)).toBeGreaterThan(0.5);
		expect(opaque).toBeGreaterThan(20_000);
		// The corners are transparent, never a white tile a launcher would tint solid.
		expect(png.pixels[3]).toBe(0);
	});

	it.each(['apple-touch-icon.png', 'apple-touch-icon-pro.png'])(
		'%s: 180×180 with no transparent pixel (iOS paints those black)',
		(name) => {
			const png = readPng(`static/icons/${name}`);
			expect([png.width, png.height]).toEqual([180, 180]);
			for (let i = 3; i < png.pixels.length; i += 4) expect(png.pixels[i]).toBe(255);
		}
	);
});

describe('Pro icons (FN-46 Part 3)', () => {
	/** The light --pro of docs/design/tokens.css, the crown's colour in the icons. */
	const CROWN = [0xa2, 0x76, 0x0a];
	const css = readFileSync('docs/design/tokens.css', 'utf8');

	it('exactly three, twins of the Gratis 192, 512 and apple-touch icons, the crown in the light --pro', () => {
		expect(PRO_ICONS.map((s) => s.file)).toEqual([
			'icons/icon-192-pro.png',
			'icons/icon-512-pro.png',
			'icons/apple-touch-icon-pro.png'
		]);
		expect(css.slice(0, css.indexOf('}'))).toContain('--pro: #a2760a;');
	});

	it.each(PRO_ICONS.map((s) => [s.file, s] as const))(
		'%s: Koko (black fur, ink outline) with a gold crown on the head, between the ears',
		(file, spec) => {
			const png = readPng(`static/${file}`);
			expect([png.width, png.height]).toEqual([spec.size, spec.size]);
			const at = (x: number, y: number) =>
				png.pixels.subarray((y * png.width + x) * 4, (y * png.width + x) * 4 + 3);
			const isFur = ([r, g, b]: Uint8Array) => r === 0x3a && g === 0x33 && b === 0x2f;
			const isCrown = ([r, g, b]: Uint8Array) => r === CROWN[0] && g === CROWN[1] && b === CROWN[2];
			let fur = 0;
			let crown = 0;
			let crownBottom = -1;
			let [crownLeft, crownRight] = [png.width, -1];
			for (let y = 0; y < png.height; y++)
				for (let x = 0; x < png.width; x++) {
					if (isFur(at(x, y))) fur++;
					if (isCrown(at(x, y))) {
						crown++;
						crownBottom = Math.max(crownBottom, y);
						crownLeft = Math.min(crownLeft, x);
						crownRight = Math.max(crownRight, x);
					}
				}
			// The highest fur under the crown's columns (the head; the ears stand either side of the crown).
			let furTop = png.height;
			for (let y = 0; y < png.height && furTop === png.height; y++)
				for (let x = crownLeft; x <= crownRight; x++) if (isFur(at(x, y))) furTop = y;
			expect(fur / (png.width * png.height)).toBeGreaterThan(0.08);
			expect(crown).toBeGreaterThan(spec.cell * spec.cell * 10);
			expect(crownBottom).toBeLessThan(furTop);
		}
	);

	it('the Gratis icons carry no crown', () => {
		for (const spec of ICONS) {
			const png = readPng(`static/${spec.file}`);
			for (let i = 0; i < png.pixels.length; i += 4)
				expect(
					png.pixels[i] === CROWN[0] &&
						png.pixels[i + 1] === CROWN[1] &&
						png.pixels[i + 2] === CROWN[2]
				).toBe(false);
		}
	});
});

describe('app.html links and the favicon', () => {
	it('the icon and apple-touch-icon links resolve to files in static/, for either plan look (FN-46)', () => {
		const html = readFileSync('src/app.html', 'utf8');
		const hrefs = [
			...html.matchAll(/<link rel="(icon|apple-touch-icon)" href="%sveltekit\.assets%([^"]+)"/g)
		].map((m) => [m[1], m[2]!] as const);
		expect(hrefs.map(([rel]) => rel)).toEqual(['icon', 'apple-touch-icon']);
		expect(hrefs[1]![1]).toBe('/icons/%fin.appleTouchIcon%');
		for (const plan of ['gratis', 'pro', 'agen'] as const)
			for (const [, href] of hrefs) {
				const path = href.replace('%fin.appleTouchIcon%', appleTouchIconFile(plan));
				expect(existsSync(`static${path}`), path).toBe(true);
			}
	});

	it('the manifest link sends cookies, so a Pro account gets its own icons (FN-46 red team L1)', () => {
		const html = readFileSync('src/app.html', 'utf8');
		const link = html.match(/<link\s[^>]*rel="manifest"[^>]*>/)?.[0] ?? '';
		expect(link).toMatch(/href="%sveltekit\.assets%\/manifest\.webmanifest"/);
		expect(link).toMatch(/crossorigin="use-credentials"/);
	});

	it('static/favicon.svg is the generator output: Koko on its 24×24 grid, inline, no external reference', () => {
		const svg = readFileSync('static/favicon.svg', 'utf8');
		expect(svg).toBe(faviconSvg());
		expect(svg).toMatch(/viewBox="0 0 24 24"/);
		expect(svg).not.toMatch(/<(image|use|script|foreignObject)\b|href=|url\(/);
		expect((svg.match(/<rect /g) ?? []).length).toBeGreaterThan(20);
	});
});
